fields.InputDefinition:
{
  "goal": "You are logged in at http://localhost:4200. Then walk these command-palette behaviors IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) palette-jump-to-app — press Ctrl+/ (Windows/Linux) or Cmd+/ (Mac) to open the command palette (a centered modal search box with an application list), type an application name such as 'Admin' and confirm the results list narrows to matching applications as you type, then click the matching application (or press Enter with it highlighted) and confirm that app opens/loads (its landing/section renders); (2) palette-no-match — reopen the command palette (Ctrl+/ or Cmd+/), type a nonsense string that matches no application such as 'zzzqqqxyz', and confirm the palette responds with a clear no-results state (a 'No applications found' empty-state and/or a fallback action such as 'Search Knowledge Hub' for the typed text) rather than showing stale/leftover application results or crashing. Keep going until both branches are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "palette-jump-to-app",
      "instruction": "Palette fuzzy-filters and navigates to an application",
      "visualCriteria": [
        "The command palette modal opens with a search input and a list of applications, typing an app name narrows the list to matching application(s), and selecting a result navigates to that application (its landing/section renders)"
      ]
    },
    {
      "name": "palette-no-match",
      "instruction": "Palette no-match empty state",
      "visualCriteria": [
        "Typing a gibberish no-match query into the command palette shows a clear no-results/empty state (e.g. 'No applications found') and/or a Knowledge/Search fallback action row, with no unrelated leftover application results and no crash"
      ]
    }
  ]
}
